CREATE TABLE organizations (id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE users (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL);
CREATE TABLE projects (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, repository_id text NOT NULL, latest_seq bigint NOT NULL DEFAULT 0);
CREATE TABLE project_memberships (project_id uuid REFERENCES projects(id), user_id uuid REFERENCES users(id), PRIMARY KEY(project_id,user_id));
CREATE TABLE devices (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE agent_sessions (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), user_id uuid NOT NULL REFERENCES users(id), device_id uuid NOT NULL REFERENCES devices(id), agent text NOT NULL, device_name text NOT NULL, last_seen timestamptz NOT NULL DEFAULT now(), online boolean NOT NULL DEFAULT true, ended_at timestamptz, observation jsonb, UNIQUE(project_id,id));
CREATE INDEX session_presence ON agent_sessions(project_id, online, last_seen);
CREATE TABLE tasks (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), title text NOT NULL, detail text, definition_of_done text, depends_on uuid[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'todo' CHECK(status IN ('todo','doing','blocked','done','cancelled')), version integer NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES agent_sessions(id), updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,id));
CREATE TABLE task_claims (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), task_id uuid NOT NULL UNIQUE, session_id uuid NOT NULL, claimed_at timestamptz NOT NULL DEFAULT now(), lease_expires_at timestamptz NOT NULL, FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,session_id) REFERENCES agent_sessions(project_id,id));
CREATE TABLE work_intents (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), session_id uuid NOT NULL UNIQUE, task_id uuid, summary text NOT NULL, base_commit text, paths jsonb NOT NULL, version integer NOT NULL DEFAULT 1, expires_at timestamptz NOT NULL, FOREIGN KEY(project_id,session_id) REFERENCES agent_sessions(project_id,id), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), UNIQUE(project_id,id));
CREATE TABLE conflicts (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), fingerprint text NOT NULL, body jsonb NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, UNIQUE(project_id,fingerprint));
CREATE INDEX conflicts_active ON conflicts(project_id,status);
CREATE TABLE messages (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), session_id uuid NOT NULL, recipient jsonb NOT NULL, kind text NOT NULL, body text NOT NULL, refs uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,session_id) REFERENCES agent_sessions(project_id,id));
CREATE TABLE project_facts (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), session_id uuid NOT NULL, type text NOT NULL, title text NOT NULL, statement text NOT NULL, structured jsonb, status text NOT NULL DEFAULT 'proposed', provenance jsonb, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,session_id) REFERENCES agent_sessions(project_id,id));
CREATE TABLE handoffs (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), task_id uuid NOT NULL, from_session_id uuid NOT NULL, recipient jsonb NOT NULL, body jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', version integer NOT NULL DEFAULT 1, accepted_by uuid, accepted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(project_id,task_id) REFERENCES tasks(project_id,id), FOREIGN KEY(project_id,from_session_id) REFERENCES agent_sessions(project_id,id), FOREIGN KEY(project_id,accepted_by) REFERENCES agent_sessions(project_id,id));
CREATE TABLE project_events (event_id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), seq bigint NOT NULL, type text NOT NULL, timestamp timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL, UNIQUE(project_id,seq));
CREATE TABLE idempotency_keys (project_id uuid NOT NULL, session_id uuid NOT NULL, key text NOT NULL, digest text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,session_id,key), FOREIGN KEY(project_id,session_id) REFERENCES agent_sessions(project_id,id));
CREATE INDEX memberships_user ON project_memberships(user_id,project_id);
CREATE INDEX tasks_project_created ON tasks(project_id,created_at DESC);
CREATE INDEX claims_project_expiry ON task_claims(project_id,lease_expires_at);
CREATE INDEX intents_project_expiry ON work_intents(project_id,expires_at);
CREATE INDEX messages_project_created ON messages(project_id,created_at DESC);
CREATE INDEX facts_project_created ON project_facts(project_id,created_at DESC);
CREATE INDEX handoffs_project_created ON handoffs(project_id,created_at DESC);

CREATE TABLE audit_events (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), user_id uuid NOT NULL REFERENCES users(id), device_id uuid NOT NULL REFERENCES devices(id), session_id uuid REFERENCES agent_sessions(id), operation text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_project_created ON audit_events(project_id,created_at DESC);
